import { type ReactNode, useCallback, useState } from "react";
import { IndexAwareNestedApp } from "./NestedAppReact";
import { Markdown } from "../Markdown/Markdown";
import type { ThemeTone } from "../../abstractions/ThemingDefs";
import { ThemedButton as Button } from "../Button/Button";
import styles from "./NestedApp.module.scss";
import { Tooltip } from "./Tooltip";
import { createQueryString, withoutTrailingSlash } from "./utils";
import { useAppContext } from "../../components-core/AppContext";
import classnames from "classnames";
import Logo from "./logo.svg?react";
import { useTheme, useThemes } from "../../components-core/theming/ThemeContext";
import { ThemedIcon } from "../Icon/Icon";

type AppWithCodeViewReactProps = {
  // Markdown content to display in the left column
  markdown: string;
  // Display layout in side-by-side mode (horizontal) when true,
  // or stacked (vertical) when false or undefined
  splitView?: boolean;
  // Indicates that the split view should initially show the code
  initiallyShowCode?: boolean;
  // Optional URL for the playground pop-out
  popOutUrl?: string;
  api?: any;
  app: string;
  components?: any[];
  config?: any;
  activeTone?: ThemeTone;
  activeTheme?: string;
  title?: string;
  height?: string | number;
  allowPlaygroundPopup?: boolean;
  withFrame?: boolean;
  allowReset?: boolean;
  noHeader?: boolean;
  immediate?: boolean;
  withSplashScreen?: boolean;
  closeButton?: ReactNode;
  controlsWidth?: string | number;
};

export const DEFAULT_IMPLICIT_PLAYGROUND_HEIGHT = "320px";
const LOCAL_TONE_CONTROLLER_PATTERN = /<\s*(ToneSwitch|ToneChangerButton)(?=[\s/>])/;

function hasLocalToneController(app: string, components: any[] = []) {
  return (
    LOCAL_TONE_CONTROLLER_PATTERN.test(app) ||
    components.some(
      (component) =>
        typeof component === "string" && LOCAL_TONE_CONTROLLER_PATTERN.test(component),
    )
  );
}

/**
 * A component that displays markdown content on the left and a NestedApp on the right
 */
export function AppWithCodeViewReact({
  markdown,
  splitView,
  withFrame = true,
  allowReset = true,
  noHeader = false,
  initiallyShowCode = false,
  popOutUrl,
  app,
  api,
  components = [],
  config,
  activeTone,
  activeTheme,
  title,
  height,
  allowPlaygroundPopup,
  withSplashScreen,
  immediate,
  closeButton = null,
  controlsWidth,
}: AppWithCodeViewReactProps): ReactNode {
  const [showCode, setShowCode] = useState(initiallyShowCode);
  const appContext = useAppContext();
  const [refreshVersion, setRefreshVersion] = useState(0);
  const { activeThemeTone, activeThemeId } = useTheme();
  const { themes: allThemes } = useThemes();

  // Forward the parent app's registered themes and active theme into the nested
  // playground so playgrounds inherit the host's look-and-feel by default.
  // Precedence for the active theme:
  //   1. explicit `activeTheme` prop (caller override),
  //   2. playground's own `config.defaultTheme` (author's choice),
  //   3. host app's `activeThemeId` (fallback).
  const effectiveConfig = {
    ...(config || {}),
    themes: [...((config?.themes as any[]) || []), ...(allThemes || [])],
  };
  const effectiveActiveTheme = activeTheme || config?.defaultTheme || activeThemeId;
  const hasLocalThemes = Array.isArray(config?.themes) && config.themes.length > 0;
  const hasLocalToneSwitcher = hasLocalToneController(app, components);
  const inheritsHostTheme =
    activeTheme === undefined &&
    config?.defaultTheme === undefined &&
    activeTone === undefined &&
    config?.defaultTone === undefined &&
    !hasLocalThemes &&
    !hasLocalToneSwitcher;
  const effectiveHeight = height ?? DEFAULT_IMPLICIT_PLAYGROUND_HEIGHT;
  const shouldMountImmediately = immediate ?? false;

  const safePopOutUrl = withoutTrailingSlash(
    popOutUrl || appContext?.appGlobals?.popOutUrl || "https://playground.xmlui.org/#/playground",
  );
  const openPlayground = useCallback(async () => {
    const themeForExport = allThemes.find((t) => t.id === activeThemeId);
    const data = {
      standalone: {
        app,
        components,
        config: {
          name: title,
          themes: themeForExport ? [themeForExport] : [],
          defaultTheme: activeTheme,
        },
        api: api,
      },
      options: {
        fixedTheme: false,
        swapped: false,
        previewMode: false,
        orientation: "horizontal",
        activeTheme: activeThemeId || activeTheme,
        activeTone: activeTone || activeThemeTone,
        content: "app",
      },
    };
    const appQueryString = await createQueryString(JSON.stringify(data));
    window.open(`${safePopOutUrl}/#${appQueryString}`, "_blank", "noopener,noreferrer");
  }, [allThemes, app, components, title, activeTheme, api, activeThemeId, activeTone, activeThemeTone, safePopOutUrl]);

  if (withFrame) {
    return (
      <>
        {!!markdown && !splitView && <Markdown>{markdown}</Markdown>}
        <div className={styles.nestedAppContainer} style={{ height: effectiveHeight }}>
          {!noHeader && (
            <div className={styles.header}>
              {!splitView && <span className={styles.headerText}>{title}</span>}
              {splitView && (
                <>
                  <div className={styles.wrapper} style={{ width: controlsWidth }}>
                    <Logo className={styles.logo} />
                  </div>
                  <div className={styles.viewControls}>
                    <Button
                      onClick={() => setShowCode(true)}
                      className={classnames(styles.splitViewButton, {
                        [styles.show]: showCode,
                        [styles.hide]: !showCode,
                      })}
                    >
                      XML
                    </Button>
                    <Button
                      onClick={() => setShowCode(false)}
                      className={classnames(styles.splitViewButton, {
                        [styles.show]: !showCode,
                        [styles.hide]: showCode,
                      })}
                    >
                      UI
                    </Button>
                  </div>
                </>
              )}
              <div className={styles.controlWrapper} style={{ width: controlsWidth }}>
                {allowPlaygroundPopup && (
                  <Tooltip
                    trigger={
                      <button
                        className={styles.headerButton}
                        onClick={() => {
                          void openPlayground();
                        }}
                      >
                        <ThemedIcon name="hyperlink" size="sm" />
                      </button>
                    }
                    label="View and edit in new full-width window"
                  />
                )}
                {allowReset && (
                  <Tooltip
                    trigger={
                      <button
                        className={styles.headerButton}
                        onClick={() => {
                          setShowCode(false);
                          setRefreshVersion(refreshVersion + 1);
                        }}
                      >
                        <ThemedIcon name="refresh" size="sm" />
                      </button>
                    }
                    label="Reset the app"
                  />
                )}
                {closeButton}
              </div>
            </div>
          )}
          <div className={styles.contentContainer}>
            <Markdown
              className={classnames(styles.splitViewMarkdown, { [styles.hidden]: !showCode })}
            >
              {markdown}
            </Markdown>
            <IndexAwareNestedApp
              className={classnames({ [styles.hidden]: showCode })}
              height="100%"
              app={app}
              api={api}
              components={components}
              config={effectiveConfig}
              activeTone={activeTone}
              activeTheme={effectiveActiveTheme}
              inheritsHostTheme={inheritsHostTheme}
              refreshVersion={refreshVersion}
              withSplashScreen={withSplashScreen}
              immediate={shouldMountImmediately}
            />
          </div>
        </div>
      </>
    );
  }
  return (
    <>
      {!!markdown && <Markdown>{markdown}</Markdown>}
      <IndexAwareNestedApp
        height={effectiveHeight}
        app={app}
        api={api}
        components={components}
        config={effectiveConfig}
        activeTone={activeTone}
        activeTheme={effectiveActiveTheme}
        inheritsHostTheme={inheritsHostTheme}
        refreshVersion={refreshVersion}
        withSplashScreen={withSplashScreen}
        immediate={shouldMountImmediately}
      />
    </>
  );
}

/**
 * Export a named default for easier imports
 */
export default AppWithCodeViewReact;
