// --- CSS properties of a particular DateInput variant
@mixin variant($variantName) {
  $suffix: if($variantName != "", "--#{$variantName}", "");
  border-radius: createThemeVar("Input:borderRadius-#{$componentName}#{$suffix}");
  border-color: createThemeVar("Input:borderColor-#{$componentName}#{$suffix}");
  border-width: createThemeVar("Input:borderWidth-#{$componentName}#{$suffix}");
  border-style: createThemeVar("Input:borderStyle-#{$componentName}#{$suffix}");
  background-color: createThemeVar("Input:backgroundColor-#{$componentName}#{$suffix}");
  box-shadow: createThemeVar("Input:boxShadow-#{$componentName}#{$suffix}");
  color: createThemeVar("Input:textColor-#{$componentName}#{$suffix}");
  font-size: createThemeVar("Input:fontSize-#{$componentName}#{$suffix}");

  &:hover {
    border-color: createThemeVar("Input:borderColor-#{$componentName}#{$suffix}--hover");
    background-color: createThemeVar(
      "Input:backgroundColor-#{$componentName}#{$suffix}--hover"
    );
    box-shadow: createThemeVar("Input:boxShadow-#{$componentName}#{$suffix}--hover");
    color: createThemeVar("Input:textColor-#{$componentName}#{$suffix}--hover");
  }

  &:focus-within {
    border-color: createThemeVar("Input:borderColor-#{$componentName}#{$suffix}--focus");
    background-color: createThemeVar(
      "Input:backgroundColor-#{$componentName}#{$suffix}--focus"
    );
    box-shadow: createThemeVar("Input:boxShadow-#{$componentName}#{$suffix}--focus");
    color: createThemeVar("Input:textColor-#{$componentName}#{$suffix}--focus");
  }

  &:has(.dateInputWrapper input:focus-visible) {
    outline-width: createThemeVar("Input:outlineWidth-#{$componentName}#{$suffix}--focus");
    outline-color: createThemeVar("Input:outlineColor-#{$componentName}#{$suffix}--focus");
    outline-style: createThemeVar("Input:outlineStyle-#{$componentName}#{$suffix}--focus");
    outline-offset: createThemeVar("Input:outlineOffset-#{$componentName}#{$suffix}--focus");
  }

  .adornment {
    color: createThemeVar("Input:color-adornment-#{$componentName}#{$suffix}");
  }
}

@layer components {
  .dateInputWrapper {
    display: flex;
    align-items: center;
    width: fit-content;
    height: max-content;
    min-height: $minHeight-DateInput;
    line-height: normal;
    border-style: solid;
    border-width: 1px;
    transition: $transition-background-DateInput;
    overflow: hidden;
    gap: $gap-adornment-DateInput;
    @include t.paddingVars($themeVars, $componentName);

    &.disabled {
      opacity: $opacity-DateInput--disabled;
      pointer-events: none;
    }
    
    &.readOnly {
      .dateInputWrapper input {
        cursor: default;
      }
    }

    @include variant("");

    &.error {
      @include variant("error");
    }
    &.warning {
      @include variant("warning");
    }
    &.valid {
      @include variant("success");
    }

    &:has(input:is(:disabled)) {
      cursor: not-allowed;
      background-color: $backgroundColor-DateInput--disabled;
      color: $textColor-DateInput--disabled;
      border-color: $borderColor-DateInput--disabled;
    }

    button {
      background: transparent;
      border: none;
      cursor: pointer;
      color: inherit;
      padding: $padding-button-DateInput;
      border-radius: $borderRadius-DateInput;

      &:hover {
        background-color: $backgroundColor-DateInput--hover;
      }

      &:focus {
        outline-width: $outlineWidth-button-DateInput--focused;
        outline-color: $outlineColor-button-DateInput--focused;
        outline-offset: $outlineOffset-button-DateInput--focused;
        outline-style: solid;
      }

      &:disabled {
        cursor: not-allowed;
        opacity: $opacity-DateInput--disabled;
      }
    }
  }

  // DateInput internal components styling
  .wrapper {
    display: flex;
    flex-grow: 0; // Don't grow to eliminate unused space
    flex-shrink: 0; // Don't shrink to maintain consistency
  }

  .inputGroup {
    display: flex;
    align-items: center;
    flex-grow: 0; // Don't grow to eliminate unused space
    flex-shrink: 0; // Don't shrink to maintain consistency
    min-width: 0; // Allow shrinking if needed
    gap: 0; // Remove gap since dividers handle spacing
    box-sizing: border-box;
  }

  .selectAllActive {
    .input {
      background-color: Highlight;
      color: HighlightText;
    }
  }

  .divider {
    padding: 0 0.25rem; // Increase horizontal spacing around dividers
    white-space: pre;
    display: inline-block;
    font: inherit;
    color: $color-divider-DateInput;
  }

  .input {
    min-width: $minWidth-input-DateInput;
    height: 100%;
    position: relative;
    padding: $padding-input-DateInput;
    border: 0;
    background: none;
    color: currentColor;
    box-sizing: content-box;
    border-radius: $borderRadius-input-DateInput;
    -webkit-appearance: textfield;
    -moz-appearance: textfield;
    appearance: textfield;

    // Consistent width for all date inputs (following TimeInput strategy)
    &.day,
    &.month,
    &.year {
      width: 2.5ch; // Uniform width following TimeInput pattern
      min-width: 2.5ch;
      max-width: 2.5ch;
      text-align: start;
      padding: $padding-input-DateInput !important;
      box-sizing: border-box !important;
    }

    &.year {
      width: 4.5ch;
      min-width: 4.5ch;
      max-width: 4.5ch;
    }

    // Hide spin buttons for number inputs
    &::-webkit-outer-spin-button,
    &::-webkit-inner-spin-button {
      -webkit-appearance: none !important;
      -moz-appearance: none !important;
      appearance: none !important;
      margin: 0 !important;
      display: none !important;
    }

    // Hide spin buttons for Firefox
    &[type="number"] {
      -moz-appearance: textfield !important;
      appearance: textfield !important;
    }

    &:invalid {
      background-color: $backgroundColor-input-DateInput-invalid;
    }

    &.invalid {
      background-color: $backgroundColor-input-DateInput-invalid;
    }
  }

  button.clearButton {
    height: auto;
    padding-block: 0;
  }
}

// Export theme variables for consumption by the component definition
:export {
  themeVars: t.json-stringify($themeVars);
}
