export const COMPOUND_COMP_ID = "Component";
export const UCRegex = /^[A-Z]/;
export const onPrefixRegex = /^on[A-Z]/;
const propAttrs = ["name", "value"];

const CDATA_PREFIX_LEN = 9;
const CDATA_POSTFIX_LEN = 3;
const COMPONENT_NAMESPACE_SCHEME = "component-ns";
const APP_NS_KEY = "app-ns";
const APP_NS_VALUE = "#app-ns";
const CORE_NS_KEY = "core-ns";
export const CORE_NAMESPACE_VALUE = "#xmlui-core-ns";
const COMPILED_EVENT_HANDLER_SOURCE_LOGGING_ENABLED = false;

/** Nodes which got modified or added during transformation keep their own text,
 * since they are not present in the original source text */
interface TransformNode extends Node {
  text?: string;
  originalKind?: SyntaxKind;
}

function logCompiledEventHandlerSource(sourceId: string, sourceText: string, js: string): void {
  if (typeof console === "undefined") return;
  const title = `[xmlui] compiled event handler ${sourceId}`;
  if (typeof console.groupCollapsed === "function") {
    console.groupCollapsed(title);
    console.log("sourceId:", sourceId);
    console.log("source:", sourceText);
    console.log("js:", js);
    console.groupEnd?.();
    return;
  }
  console.log(title, { sourceId, source: sourceText, js });
}

const HelperNode = {
  property: "property",
  template: "template",
  event: "event",
  variable: "variable",
  global: "global",
  loaders: "loaders",
  uses: "uses",
  method: "method",
  item: "item",
  field: "field",
} as const;

/**
 * Reserved declaration tag names that may appear as direct children of a
 * `<Component>` (compound-component definition).  Used by the UDC sandbox
 * (plan #14) to describe the public contract of a UDC.
 *
 * These names are intentionally PascalCase so that they do not collide with
 * the lowercase `HelperNode` tags (`event`, `method`, `property`, …).
 */
const UDC_DECLARATION_KINDS = {
  Prop: "Prop",
  Event: "Event",
  Method: "Method",
  Slot: "Slot",
} as const;

/**
 * Locally-typed shape used by the parser when building a UDC contract.
 * Kept here (rather than imported from `components-core/udc-sandbox`) to
 * preserve the parser's layering: `parsers/*` must not depend on
 * `components-core/*`.  Consumers should cast to the canonical
 * `UdcPropDecl` from `components-core/udc-sandbox`.
 */
interface UdcPropDecl {
  name: string;
  type?: string;
  required?: boolean;
  defaultValue?: unknown;
}

type UdcTrust = "trusted" | "untrusted";
type UdcCapability =
  | "fetch"
  | "websocket"
  | "eventsource"
  | "navigate"
  | "clipboard"
  | "randomBytes"
  | "log"
  | "mark"
  | "environment";

const ALL_UDC_CAPABILITIES: readonly UdcCapability[] = [
  "fetch",
  "websocket",
  "eventsource",
  "navigate",
  "clipboard",
  "randomBytes",
  "log",
  "mark",
  "environment",
];

function parseUdcCapabilities(value: string | undefined): Set<UdcCapability> {
  if (value === undefined) return new Set(ALL_UDC_CAPABILITIES);
  const parsed = new Set<UdcCapability>();
  for (const raw of value.split(",")) {
    const token = raw.trim();
    if ((ALL_UDC_CAPABILITIES as readonly string[]).includes(token)) {
      parsed.add(token as UdcCapability);
    }
  }
  return parsed;
}

function parseSlotProvides(value: string | undefined): Set<string> {
  if (!value) return new Set();
  return new Set(
    value
      .split(",")
      .map((item) => item.trim())
      .filter(Boolean)
      .map((item) => (item.startsWith("$") ? item : `$${item}`)),
  );
}

let lastParseId = 0;

export function nodeToComponentDef(
  node: Node,
  originalGetText: GetText,
  fileId: string | number,
  preResolvedImports?: CollectedDeclarations,
  warnings?: string[],
  cursor?: DocumentCursor,
  parserOptions: XmluiParserOptions = {},
): ComponentDef | CompoundComponentDef | null {
  return transformXmluiNode(
    node,
    originalGetText,
    fileId,
    preResolvedImports,
    warnings,
    cursor,
    "component",
    parserOptions,
  ).component;
}

export type XmluiAppParts = {
  entrypoint: ComponentDef | null;
  inlineComponents: CompoundComponentDef[];
};

export function nodeToXmluiAppParts(
  node: Node,
  originalGetText: GetText,
  fileId: string | number,
  preResolvedImports?: CollectedDeclarations,
  warnings?: string[],
  cursor?: DocumentCursor,
  parserOptions: XmluiParserOptions = {},
): XmluiAppParts {
  const { component, inlineComponents } = transformXmluiNode(
    node,
    originalGetText,
    fileId,
    preResolvedImports,
    warnings,
    cursor,
    "entrypoint",
    parserOptions,
  );

  return {
    entrypoint: component as ComponentDef | null,
    inlineComponents,
  };
}

function transformXmluiNode(
  node: Node,
  originalGetText: GetText,
  fileId: string | number,
  preResolvedImports: CollectedDeclarations | undefined,
  warnings: string[] | undefined,
  cursor: DocumentCursor | undefined,
  role: "component" | "entrypoint",
  parserOptions: XmluiParserOptions,
): {
  component: ComponentDef | CompoundComponentDef | null;
  inlineComponents: CompoundComponentDef[];
} {
  const getText = (node: TransformNode) => {
    return node.text ?? originalGetText(node);
  };

  const usesStack: Map<string, string>[] = [];
  const namespaceStack: Map<string, string>[] = [];
  const seenUids = new Set<string>();
  const topLevelElements = (node.children ?? []).filter(
    (child) => child.kind === SyntaxKind.ElementNode,
  );

  if (role === "component") {
    const element = topLevelElements[0];
    if (!element) {
      return { component: null, inlineComponents: [] };
    }
    const preppedElement = prepNode(element);
    return {
      component: transformTopLvlElement(usesStack, preppedElement),
      inlineComponents: [],
    };
  }

  const inlineComponents: CompoundComponentDef[] = [];
  let appElement: Node | undefined;

  for (const element of topLevelElements) {
    const preppedElement = prepNode(element);
    if (getComponentName(preppedElement, getText) === COMPOUND_COMP_ID) {
      const inlineComponent = transformTopLvlElement(usesStack, preppedElement);
      if (inlineComponent) {
        inlineComponents.push(inlineComponent as CompoundComponentDef);
      }
      continue;
    }
    appElement = preppedElement;
  }

  if (!appElement) {
    warnings?.push(
      `${String(fileId)} contains only inline component definitions; rendering an empty Fragment.`,
    );
    return {
      component: createEmptyFragmentComponent(),
      inlineComponents,
    };
  }

  return {
    component: transformTopLvlElement(usesStack, appElement),
    inlineComponents,
  };

  function transformTopLvlElement(
    usesStack: Map<string, string>[],
    node: Node,
  ): ComponentDef | CompoundComponentDef | null {
    const name = getNamespaceResolvedComponentName(node, getText, namespaceStack);

    if (name === COMPOUND_COMP_ID) {
      return collectCompoundComponent(node);
    }

    let component: ComponentDef = {
      type: name,
      debug: {
        source: sourceLocationFor(node),
      },
    };

    // --- Done
    collectTraits(usesStack, component, node, true);
    hoistScriptCollectedFromFragments(component);
    return component;
  }

  function createEmptyFragmentComponent(): ComponentDef {
    const source = sourceLocationFor({
      kind: SyntaxKind.ElementNode,
      pos: 0,
      end: 0,
    } as Node);
    return {
      type: "Fragment",
      debug: {
        source,
      },
    };
  }

  function transformInnerElement(
    usesStack: Map<string, string>[],
    node: Node,
    allowGlobalVars: boolean = false,
  ): ComponentDef | CompoundComponentDef | null {
    const name = getNamespaceResolvedComponentName(node, getText, namespaceStack);

    let component: ComponentDef = {
      type: name,
      debug: {
        source: sourceLocationFor(node),
      },
    };

    // --- Done
    collectTraits(usesStack, component, node, allowGlobalVars);
    hoistScriptCollectedFromFragments(component);
    return component;
  }

  function collectCompoundComponent(node: Node) {
    const attrNodes = getAttributes(node);
    const attrs = attrNodes.map(segmentAttr);
    const compoundName = attrs.find((attr) => attr.name === "name")!;

    const codeBehind = attrs.find((attr) => attr.name === "codeBehind");
    const capabilitiesAttr = attrs.find((attr) => attr.name === "capabilities");
    const trustAttr = attrs.find((attr) => attr.name === "trust");
    const trust: UdcTrust = trustAttr?.value === "untrusted" ? "untrusted" : "trusted";

    // --- Get "method" attributes
    let api: Record<string, any> | undefined;
    const apiAttrs = attrNodes
      .map((attrNode) => ({ attrNode, segmented: segmentAttr(attrNode) }))
      .filter(({ segmented }) => segmented.startSegment === "method");
    if (apiAttrs.length > 0) {
      api = {};
      apiAttrs.forEach(({ attrNode, segmented }) => {
        api![segmented.name] = parseEvent(segmented.value, attrNode.children?.[2]);
      });
    }

    // --- Get var attributes
    let vars: Record<string, any> | undefined;
    const varsAttrs = attrNodes
      .map((attrNode) => ({ attrNode, segmented: segmentAttr(attrNode) }))
      .filter(({ segmented }) => segmented.startSegment === "var");
    if (varsAttrs.length > 0) {
      vars = {};
      varsAttrs.forEach(({ segmented }) => {
        vars![segmented.name] = segmented.value;
      });
    }

    // --- Report error for global attributes (not allowed in component definitions)
    const globalsAttrs = attrs.filter((attr) => attr.startSegment === "global");
    if (globalsAttrs.length > 0) {
      // Parser already emits globalNotAllowedInComponent for these.
    }

    const children = getChildNodes(node);

    // --- Extract declared UDC contract blocks (<Prop>, <Event>, <Method>, <Slot>)
    // These are direct-child element nodes whose tag name is one of the reserved
    // declaration kinds.  See `xmlui/dev-docs/plans/14-udc-sandbox.md`.
    //
    // Ambiguity: `<Slot>` is also the runtime template tag used inside compound
    // component templates (e.g. `<Component><Slot/></Component>`).  To avoid
    // breaking existing compound components, `<Slot>` is only treated as a
    // declaration when at least one other declaration kind (`<Prop>`, `<Event>`,
    // or `<Method>`) is also present as a direct child — that combination is the
    // explicit opt-in to the UDC declarative contract syntax.
    const declProps = new Map<string, UdcPropDecl>();
    const declEvents = new Set<string>();
    const declMethods = new Set<string>();
    const declSlots = new Set<string>();
    const declSlotProvides = new Map<string, Set<string>>();
    let hasNonSlotDeclarations = false;
    for (const child of children) {
      if (child.kind !== SyntaxKind.ElementNode) continue;
      const childName = getComponentName(child, getText);
      if (
        childName === UDC_DECLARATION_KINDS.Prop ||
        childName === UDC_DECLARATION_KINDS.Event ||
        childName === UDC_DECLARATION_KINDS.Method
      ) {
        hasNonSlotDeclarations = true;
        break;
      }
    }
    const isDeclarationKind = (name: string) =>
      name === UDC_DECLARATION_KINDS.Prop ||
      name === UDC_DECLARATION_KINDS.Event ||
      name === UDC_DECLARATION_KINDS.Method ||
      (hasNonSlotDeclarations && name === UDC_DECLARATION_KINDS.Slot);
    let hasDeclarations = false;

    for (const child of children) {
      if (child.kind !== SyntaxKind.ElementNode) continue;
      const childName = getComponentName(child, getText);
      if (!isDeclarationKind(childName)) continue;
      hasDeclarations = true;
      const declAttrs = getAttributes(child).map(segmentAttr);
      const nameAttr = declAttrs.find((a) => a.name === "name");
      if (!nameAttr || !nameAttr.value) continue;
      switch (childName) {
        case UDC_DECLARATION_KINDS.Prop: {
          const typeAttr = declAttrs.find((a) => a.name === "type");
          const requiredAttr = declAttrs.find((a) => a.name === "required");
          const defaultAttr = declAttrs.find((a) => a.name === "defaultValue");
          declProps.set(nameAttr.value, {
            name: nameAttr.value,
            ...(typeAttr ? { type: typeAttr.value } : {}),
            ...(requiredAttr ? { required: requiredAttr.value === "true" } : {}),
            ...(defaultAttr ? { defaultValue: defaultAttr.value } : {}),
          });
          break;
        }
        case UDC_DECLARATION_KINDS.Event:
          declEvents.add(nameAttr.value);
          break;
        case UDC_DECLARATION_KINDS.Method:
          declMethods.add(nameAttr.value);
          break;
        case UDC_DECLARATION_KINDS.Slot:
          declSlots.add(nameAttr.value);
          declSlotProvides.set(
            nameAttr.value,
            parseSlotProvides(declAttrs.find((a) => a.name === "provides")?.value),
          );
          break;
      }
    }

    // --- Get the single component definition
    const nestedComponents = children.filter(
      (child) =>
        child.kind === SyntaxKind.ElementNode &&
        !(getComponentName(child, getText) in HelperNode) &&
        !isDeclarationKind(getComponentName(child, getText)),
    );

    const nonVarHelperNodes: Node[] = [];
    const nestedVars: Node[] = [];
    for (let child of children) {
      if (child.kind === SyntaxKind.ElementNode) {
        const childName = getComponentName(child, getText);
        if (childName === HelperNode.variable) {
          nestedVars.push(child);
        } else if (childName === HelperNode.global) {
          // Parser already emits globalNotAllowedInComponent for global elements in component defs.
        } else if (childName in HelperNode) {
          nonVarHelperNodes.push(child);
        }
      }
    }

    // --- Should we wrap with a Fragment?
    let nestedComponent: ComponentDef;
    let componentSourceNode: Node = node;
    if (nestedComponents.length === 0 && nestedVars.length === 0) {
      nestedComponent = createEmptyFragmentComponent();
    } else {
      const element =
        nestedComponents.length > 1 || nestedVars.length > 0
          ? wrapWithFragment([...nestedVars, ...nestedComponents])
          : nestedComponents[0];
      componentSourceNode = element;

      namespaceStack.push(new Map());
      // --- Get collect namespace attributes
      attrs
        .filter((attr) => attr.namespace === "xmlns")
        .forEach((attr) => {
          addToNamespaces(namespaceStack, element, attr.unsegmentedName, attr.value);
        });

      nestedComponent = transformInnerElement(usesStack, element, false)! as ComponentDef;
      namespaceStack.pop();
    }

    const component: CompoundComponentDef = {
      name: compoundName.value,
      component: nestedComponent,
      debug: {
        source: sourceLocationFor(node),
      },
    };

    if (api) {
      component.api = api;
    }
    if (vars) {
      nestedComponent.vars = { ...nestedComponent.vars, ...vars };
      varsAttrs.forEach(({ attrNode, segmented }) => {
        setReactiveNodeLocation(nestedComponent, "var", segmented.name, attrNode);
      });
    }
    if (codeBehind) {
      component.codeBehind = codeBehind.value;
    }

    // --- Attach declared contract when the UDC carried declaration blocks or
    // sandbox attributes (`capabilities` / `trust`).
    if (hasDeclarations || capabilitiesAttr || trustAttr) {
      component.contract = {
        name: compoundName.value,
        props: declProps,
        events: declEvents,
        methods: declMethods,
        slots: declSlots,
        slotProvides: declSlotProvides,
        capabilities: parseUdcCapabilities(capabilitiesAttr?.value),
        capabilitiesDeclared: capabilitiesAttr !== undefined,
        trust,
      };
    }

    nestedComponent.debug = {
      ...nestedComponent.debug,
      source: sourceLocationFor(componentSourceNode),
    };

    const nodeClone: Node = withNewChildNodes(node, nonVarHelperNodes);
    collectTraits(usesStack, component, nodeClone, false);
    return component;
  }

  /**
   * Collects component traits from attributes and child elements
   * @param comp Component definition
   * @param element Component element
   * @param allowGlobalVars Whether global variables are allowed in this context
   */
  function collectTraits(
    usesStack: Map<string, string>[],
    comp: ComponentDef | CompoundComponentDef,
    element: Node,
    allowGlobalVars: boolean = false,
  ): void {
    const isCompound = !isComponent(comp);

    const attributes = getAttributes(element);

    namespaceStack.push(new Map());
    // --- Process attributes
    attributes.forEach((attr: Node) => {
      // --- Process the attribute
      collectAttribute(comp, attr, allowGlobalVars);
    });
    const childNodes = getChildNodes(element);

    let hasScriptNode = false;
    // --- Process child nodes
    childNodes.forEach((child: Node) => {
      if (child.kind === SyntaxKind.Script) {
        processScriptTag(comp, child, getText);
        hasScriptNode = true;
        return;
      }

      // --- Single text element, consider it a child name
      if (child.kind === SyntaxKind.TextNode && !isCompound) {
        comp.children = mergeValue(comp.children, getText(child));
        return;
      }

      const childName = getComponentName(child, getText);
      if (isCompound && child.kind === SyntaxKind.ElementNode && !(childName in HelperNode)) {
        // --- This is the single nested component definition of a compound component,
        // --- it is already processed
        return;
      }

      // --- Element name starts with an uppercase letter
      if (!(childName in HelperNode) && !isCompound) {
        // if (UCRegex.test(childName) && !isCompound) {
        // --- This must be a child component
        // maybe here or in the transformInnerElement function, after the compound comp check
        const childComponent = transformInnerElement(usesStack, child);
        if (childComponent) {
          if (!comp.children) {
            comp.children = [childComponent as ComponentDef];
          } else {
            if (typeof comp.children === "string") {
              comp.children = [comp.children as any, childComponent];
            } else if (Array.isArray(comp.children)) {
              comp.children.push(childComponent as any);
            }
          }
        }
        return;
      }

      // --- Element with a lowercase start letter, it must be some traits of the host component
      switch (childName) {
        case "property":
        case "template":
          collectElementHelper(
            usesStack,
            comp,
            child,

            (name) => (isComponent(comp) ? comp.props?.[name] : undefined),
            (name, value) => {
              if (!isComponent(comp)) return;
              comp.props ??= {};
              comp.props[name] = value;
            },
          );
          return;

        case "event":
          collectElementHelper(
            usesStack,
            comp,
            child,

            (name) => (isComponent(comp) ? comp.events?.[name] : undefined),
            (name, value, nodeScriptContent) => {
              if (!isComponent(comp)) return;
              comp.events ??= {};
              comp.events[name] = parseEvent(value, nodeScriptContent);
            },
          );
          return;

        case HelperNode.variable:
          collectElementHelper(
            usesStack,
            comp,
            child,

            (name) => (isComponent(comp) ? comp.vars?.[name] : undefined),
            (name, value) => {
              if (!isComponent(comp)) return;
              comp.vars ??= {};
              comp.vars[name] = value;
            },
            (name) => {
              if (name.startsWith("$")) reportError(DIAGS_TRANSFORM.varNameStartsWithDollar(name));
            },
          );
          return;

        case HelperNode.global:
          if (!allowGlobalVars) {
            reportError(DIAGS_TRANSFORM.globalNotAllowedInNested);
            return;
          }
          collectElementHelper(
            usesStack,
            comp,
            child,
            (name) => (isComponent(comp) ? comp.globalVars?.[name] : undefined),
            (name, value) => {
              if (!isComponent(comp)) return;
              comp.globalVars ??= {};
              comp.globalVars[name] = value;
            },
            (name) => {
              if (name.startsWith("$")) reportError(DIAGS_TRANSFORM.varNameStartsWithDollar(name));
            },
          );
          return;

        case "loaders":
          collectLoadersElements(usesStack, comp, child);
          return;

        case "uses":
          collectUsesElements(comp, child);
          return;

        case "method":
          collectElementHelper(
            usesStack,
            comp,
            child,

            (name) => (isComponent(comp) ? comp.api?.[name] : undefined),
            (name, value, nodeScriptContent) => {
              const parsedValue = Array.isArray(value)
                ? value.map((item) => parseEvent(item, nodeScriptContent))
                : parseEvent(value, nodeScriptContent);
              comp.api ??= {};
              comp.api[name] = parsedValue;
            },
          );
          return;

        default:
          // Parser already emits invalidNodeName for unrecognised helper node names.
          return;
      }
    });

    namespaceStack.pop();
  }

  function collectAttribute(
    comp: ComponentDef | CompoundComponentDef,
    attr: Node,
    allowGlobalVars: boolean = false,
  ) {
    const { namespace, startSegment, name, value, unsegmentedName: nsKey } = segmentAttr(attr);

    const attrValueStringNode = attr.children![2];

    if (namespace === "xmlns") {
      return addToNamespaces(namespaceStack, comp, nsKey, value);
    }

    const isCompound = !isComponent(comp);
    // --- Handle single-word attributes
    if (isCompound) {
      if (name === "name" && !startSegment) {
        // --- We already processed name
        return;
      }

      if (name === "codeBehind" && !startSegment) {
        // --- We already processed codeBehind
        return;
      }

      return;
    }

    // --- Recognize special attributes by component definition type
    switch (name) {
      case "id": {
        if (seenUids.has(value)) {
          let location: string;
          if (cursor) {
            const { line, character } = cursor.positionAt(attr.pos);
            location = `line ${line + 1}, column ${character + 1}`;
          } else {
            location = `position ${attr.pos}`;
          }
          const msg =
            `Duplicate component id "${value}" detected at ${location}. ` +
            `Component ids must be unique within the same markup.`;
          if (warnings) {
            warnings.push(msg);
          } else {
            console.warn(`[xmlui] ${msg}`);
          }
        } else {
          seenUids.add(value);
        }
        comp.uid = value;
        return;
      }
      case "testId":
        comp.testId = value;
        return;
      case "automationId":
        comp.automationId = value;
        return;
      case "when":
        comp.when = value;
        return;
      case "uses":
        comp.uses = splitUsesValue(value);
        return;
      default:
        // --- Handle responsive when-* attributes (when-xs, when-sm, etc.)
        if (name.startsWith("when-")) {
          const bp = name.slice(5); // Extract breakpoint name: "xs", "sm", "md", "lg", "xl", "xxl"
          if ((MediaBreakpointKeys as readonly string[]).includes(bp)) {
            comp.responsiveWhen ??= {};
            (comp.responsiveWhen as any)[bp] = value;
            return;
          }
        }

        if (startSegment === "var") {
          if (name!.startsWith("$")) {
            reportError(DIAGS_TRANSFORM.varNameStartsWithDollar(name!));
            return;
          }
          comp.vars ??= {};
          comp.vars[name] = value;
          setReactiveNodeLocation(comp, "var", name, attr);
        } else if (startSegment === "global") {
          if (!allowGlobalVars) {
            reportError(DIAGS_TRANSFORM.globalNotAllowedInNested);
            return;
          }
          if (name!.startsWith("$")) {
            reportError(DIAGS_TRANSFORM.varNameStartsWithDollar(name!));
            return;
          }
          comp.globalVars ??= {};
          comp.globalVars[name] = value;
        } else if (startSegment === "method") {
          comp.api ??= {};
          comp.api[name] = parseEvent(value, attrValueStringNode);
          setAttributeLocation(comp, name, attr);
        } else if (startSegment === "event") {
          comp.events ??= {};
          comp.events[name] = parseEvent(value, attrValueStringNode);
          setAttributeLocation(comp, name, attr);
        } else if (onPrefixRegex.test(name)) {
          comp.events ??= {};
          const eventName = name[2].toLowerCase() + name.substring(3);
          comp.events[eventName] = parseEvent(value, attrValueStringNode);
          setAttributeLocation(comp, eventName, attr);
        } else {
          comp.props ??= {};
          comp.props[name] = value;
          setAttributeLocation(comp, name, attr);
        }
        return;
    }
  }

  function collectObjectOrArray(usesStack: Map<string, string>[], children?: Node[]): any {
    let result: any = null;

    // --- No children, it's a null object
    if (!children) return result;
    let nestedElementType: string | null = null;

    children.forEach((child) => {
      if (child.kind === SyntaxKind.TextNode) {
        result = mergeValue(result, getText(child));
        return;
      }

      if (child.kind !== SyntaxKind.ElementNode) return;
      const childName = getComponentName(child, getText);
      // --- Parse phase validates non-field/non-item children and mixed lists.
      if (childName !== "field" && childName !== "item") return;

      if (childName === "field") {
        if (!nestedElementType) {
          // --- First nested element is "field", so we have an object
          nestedElementType = childName;
          result = {};
        }
      } else if (childName === "item") {
        if (!nestedElementType) {
          // --- First nested element is "item", so we have an array
          nestedElementType = childName;
          result = [];
        }
      }

      // --- Get the field value
      let valueInfo = collectValue(usesStack, child, childName === "field");
      if (!valueInfo) {
        return null;
      }

      // --- Does the field have a value?
      if (nestedElementType === "field") {
        result[valueInfo.name!] = valueInfo.value;
      } else {
        result.push(valueInfo.value);
      }
    });
    return result;
  }

  function collectValue(
    usesStack: Map<string, string>[],
    element: Node,
    allowName = true,
    extraAllowedAttrs: string[] = [],
  ): { name?: string; value: any; valueContentNode?: Node } | null {
    const elementName = getComponentName(element, getText);
    // --- Accept only "name", "value" (and any explicitly allowed extras)
    const childNodes = getChildNodes(element);
    const nestedComponents = childNodes.filter(
      (c) => c.kind === SyntaxKind.ElementNode && UCRegex.test(getComponentName(c, getText)),
    );
    const nestedHelpers = childNodes.filter(
      (c) => c.kind === SyntaxKind.ElementNode && !UCRegex.test(getComponentName(c, getText)),
    );
    const attrNodes = getAttributes(element);
    const attrsSegmented = attrNodes.map(segmentAttr);

    const allAllowedAttrs =
      extraAllowedAttrs.length > 0 ? [...propAttrs, ...extraAllowedAttrs] : propAttrs;
    const attrProps = attrsSegmented.filter((attr) => allAllowedAttrs.indexOf(attr.name) >= 0);
    if (attrsSegmented.length > attrProps.length) return null;

    // --- Validate the "name" usage
    const nameAttr = attrProps.find((attr) => attr.name === "name");
    if (allowName) {
      if (!nameAttr?.value) return null;
    } else {
      if (nameAttr) return null;
    }
    const name = nameAttr?.value;

    // --- Get the value attribute
    const valueAttr = attrProps.find((attr) => attr.name === "value");
    if (valueAttr && valueAttr.value === undefined) {
      reportError(DIAGS_TRANSFORM.valueAttrRequired(elementName));
      return null;
    }

    // --- Let's handle a special case, when the value is a component definition
    if (name && nestedComponents.length >= 1) {
      if (nestedHelpers.length > 0) {
        reportError(DIAGS_TRANSFORM.cannotMixCompNonComp);
        return null;
      }
      // --- We expect a component definition here!
      const nestedComps = nestedComponents.map((nc) => transformInnerElement(usesStack, nc));
      return {
        name,
        value: nestedComps.length === 1 ? nestedComps[0] : nestedComps,
      };
    }

    // --- At this point, all attributes are ok, let's get the value.
    let value = valueAttr?.value;

    if (value === null) {
      return null;
    }

    if (typeof value === "string") {
      const valueAttrIdx = attrProps.findIndex((attr) => attr.name === "value");
      const valueAttrNode = attrNodes[valueAttrIdx];
      return { name, value, valueContentNode: valueAttrNode };
    }

    let valueContentNode: Node;
    if (childNodes?.[0]?.kind === SyntaxKind.TextNode) {
      valueContentNode = childNodes[0];
    }
    return { name, value: collectObjectOrArray(usesStack, childNodes), valueContentNode };
  }

  function collectLoadersElements(
    usesStack: Map<string, string>[],
    comp: ComponentDef | CompoundComponentDef,
    loaders: Node,
  ): void {
    if (!isComponent(comp)) return;

    const children = getChildNodes(loaders);
    //todo: this check seems not necesarry
    if (children.length === 0) {
      comp.loaders ??= [];
    }

    const hasAttribute = loaders.children?.some((c) => c.kind === SyntaxKind.AttributeListNode);
    if (hasAttribute) {
      reportError(DIAGS_TRANSFORM.loaderCantHave("attributes"));
      return;
    }

    children.forEach((loader) => {
      // --- Test is not supported
      if (loader.kind === SyntaxKind.TextNode) {
        reportError(DIAGS_TRANSFORM.noTextChild("loader"));
        return;
      }

      // todo: is this needed?
      // --- Just for the sake of being sure...
      // if (loader.type !== "Element") return;

      const loaderDef = transformInnerElement(usesStack, loader) as ComponentDef;

      // --- Get the uid value
      if (!loaderDef.uid) {
        reportError(DIAGS_TRANSFORM.loaderIdRequired);
        return;
      }

      // --- Check props that a loader must not have
      if ((loaderDef as any).vars) {
        reportError(DIAGS_TRANSFORM.loaderCantHave("vars"));
        return;
      }

      if ((loaderDef as any).loaders) {
        reportError(DIAGS_TRANSFORM.loaderCantHave("loaders"));
        return;
      }

      if ((loaderDef as any).uses) {
        reportError(DIAGS_TRANSFORM.loaderCantHave("uses"));
        return;
      }

      // --- Store this loader
      comp.loaders ??= [];
      comp.loaders.push(loaderDef);
    });
  }

  function collectElementHelper(
    usesStack: Map<string, string>[],
    comp: ComponentDef | CompoundComponentDef,
    child: Node,
    getter: (name: string) => any,
    setter: (name: string, value: string, valueNode?: Node) => void,
    nameValidator?: (name: string) => void,
    extraAllowedAttrs: string[] = [],
  ): void {
    // --- Compound component do not have a uses

    // --- Get the value
    const valueInfo = collectValue(usesStack, child, true, extraAllowedAttrs);
    if (!valueInfo) {
      return;
    }

    // --- Extra name validation, if required so
    nameValidator?.(valueInfo?.name ?? "");

    const name = valueInfo.name!;
    const value = valueInfo.value;
    if (valueInfo?.value !== undefined) {
      setter(name, mergeValue(getter(name), value), valueInfo.valueContentNode);
      if (getComponentName(child, getText) === HelperNode.variable) {
        setReactiveNodeLocation(comp, "var", name, valueInfo.valueContentNode ?? child);
      }
    } else {
      // --- Consider the value to be null; check optional child items
      const children = getChildNodes(child);
      const itemValue = collectObjectOrArray(usesStack, children);
      let updatedValue = getter(name);
      updatedValue = mergeValue(updatedValue, itemValue);
      setter(name, updatedValue);
      if (getComponentName(child, getText) === HelperNode.variable) {
        setReactiveNodeLocation(comp, "var", name, child);
      }
    }
  }

  function collectUsesElements(comp: ComponentDef | CompoundComponentDef, usesNode: Node): void {
    // --- Compound component do not have a uses
    if (!isComponent(comp)) return;

    const attributes = getAttributes(usesNode).map(segmentAttr);
    const valueAttr = attributes.find((attr) => attr.name === "value");
    if (!valueAttr?.value || attributes.length !== 1) return;

    // --- Extract the value
    const usesValues = splitUsesValue(valueAttr.value);
    if (comp.uses) {
      comp.uses.push(...usesValues);
    } else {
      comp.uses = usesValues;
    }
  }

  function segmentAttr(attr: Node): {
    namespace?: string;
    startSegment?: string;
    name?: string;
    value: string;
    unsegmentedName: string;
  } {
    let key = attr.children![0];
    const hasNamespace = key.children!.length === 3;
    let namespace: undefined | string;
    if (hasNamespace) {
      namespace = getText(key.children![0]);
    }
    let unsegmentedName = getText(key.children![key.children!.length - 1]);
    const segments = unsegmentedName.split(".");
    if (segments.length > 2) {
      reportError(DIAGS_TRANSFORM.invalidAttrName(unsegmentedName));
    }

    let name: string | undefined;
    let startSegment: string | undefined;

    if (segments.length === 2) {
      startSegment = segments[0];
      name = segments[1];
      if (name.trim() === "") {
        reportError(DIAGS_TRANSFORM.invalidAttrName(name));
      }
    } else {
      //TODO: remove asigning name when name === unsegmentedName. It is there for backwards compat
      name = unsegmentedName;
    }
    const valueText = getText(attr.children![2]);
    const value = valueText.substring(1, valueText.length - 1);
    return { namespace, startSegment, name, value, unsegmentedName };
  }

  function sourceLocationFor(node: Node): {
    start: number;
    end: number;
    fileId: string | number;
    line?: number;
    col?: number;
    length?: number;
  } {
    const loc: {
      start: number;
      end: number;
      fileId: string | number;
      line?: number;
      col?: number;
      length?: number;
    } = {
      start: node.pos ?? node.start ?? 0,
      end: node.end ?? node.pos ?? node.start ?? 0,
      fileId,
    };
    if (cursor) {
      const { line, character } = cursor.positionAt(loc.start);
      loc.line = line + 1;
      loc.col = character + 1;
      loc.length = Math.max(1, loc.end - loc.start);
    }
    return loc;
  }

  function sourceLocationForAttribute(attr: Node): {
    name?: ReturnType<typeof sourceLocationFor>;
    value?: ReturnType<typeof sourceLocationFor>;
    full: ReturnType<typeof sourceLocationFor>;
  } {
    const keyNode = attr.children?.[0];
    const valueNode = attr.children?.[2];
    return {
      ...(keyNode ? { name: sourceLocationFor(keyNode) } : {}),
      ...(valueNode ? { value: sourceLocationForAttributeValue(valueNode) } : {}),
      full: sourceLocationFor(attr),
    };
  }

  function sourceLocationForAttributeValue(node: Node): ReturnType<typeof sourceLocationFor> {
    const loc = sourceLocationFor(node);
    if (loc.end - loc.start >= 2) {
      loc.start += 1;
      loc.end -= 1;
      if (loc.col !== undefined) {
        loc.col += 1;
      }
      loc.length = Math.max(1, loc.end - loc.start);
    }
    return loc;
  }

  function setAttributeLocation(
    comp: ComponentDef | CompoundComponentDef,
    name: string | undefined,
    attr: Node,
  ): void {
    if (!name || !isComponent(comp)) return;
    const debug = (comp.debug ??= {});
    const attributes = ((debug as any).attributes ??= {});
    attributes[name] = sourceLocationForAttribute(attr);
  }

  function setReactiveNodeLocation(
    comp: ComponentDef | CompoundComponentDef,
    kind: "var" | "loader" | "function",
    name: string | undefined,
    node: Node,
  ): void {
    if (!name) return;
    const debug = (comp.debug ??= {});
    const reactiveNodes = ((debug as any).reactiveNodes ??= {});
    reactiveNodes[`${kind}.${name}`] = sourceLocationFor(node);
  }

  function parseEscapeCharactersInAttrValues(attrs: Node[]) {
    for (let attr of attrs) {
      const attrValue = attr.children![attr.children!.length - 1] as TransformNode;
      const escapedText = tryEscapeEntities(getText(attrValue));
      if (escapedText !== null) {
        attrValue.text = escapedText;
      }
    }
  }

  function prepNode(node: Node): Node {
    const childNodes: TransformNode[] = getChildNodes(node);
    const tagName = getComponentName(node, getText);
    const hasComponentName = !(tagName in HelperNode);
    const shouldUseTextNodeElement =
      hasComponentName || tagName === "property" || tagName === "template";
    const shouldCollapseWhitespace = tagName !== "event" && tagName !== "method";
    const attrs = getAttributes(node);

    desugarKeyOnlyAttrs(attrs);
    parseEscapeCharactersInAttrValues(attrs);
    parseEscapeCharactersInContent(childNodes);

    mergeConsecutiveTexts(childNodes, shouldCollapseWhitespace);
    let shouldUseCData = false;
    let hasScriptChild = false;

    for (let i = 0; i < childNodes.length; ++i) {
      const child = childNodes[i];
      let newChild: TransformNode;

      if (child.kind == SyntaxKind.Script) {
        hasScriptChild = true;
        continue;
      }
      if (child.kind === SyntaxKind.ElementNode) {
        newChild = prepNode(child);
        childNodes[i] = newChild;
        continue;
      }

      let textValue = getText(child);

      if (child.kind === SyntaxKind.CData) {
        shouldUseCData = true;
      }

      if (shouldUseTextNodeElement) {
        if (shouldUseCData) {
          newChild = createTextNodeCDataElement(textValue, child.kind);
        } else {
          newChild = createTextNodeElement(textValue, child.kind);
        }
      } else {
        newChild = {
          kind: SyntaxKind.TextNode,
          text: textValue,
          pos: child.pos,
          end: child.end,
          originalKind: child.kind,
        } as TransformNode;
      }
      childNodes[i] = newChild;
    }

    const helperNodes = [];
    const otherNodes = [];
    let hasComponentChild = false;
    for (const child of childNodes) {
      if (child.kind === SyntaxKind.ElementNode) {
        let compName: string = getComponentName(child, getText) ?? undefined;
        if (compName in HelperNode) {
          helperNodes.push(child);
          continue;
        }
        hasComponentChild = true;
      }
      otherNodes.push(child);
    }

    if (hasScriptChild && hasComponentChild) {
      const fragment = wrapWithFragment(otherNodes);
      helperNodes.push(fragment);
      return withNewChildNodes(node, helperNodes);
    }

    return node;
  }

  function collapseWhitespace(childNodes: TransformNode[]) {
    for (let i = 0; i < childNodes.length; ++i) {
      if (childNodes[i].kind === SyntaxKind.TextNode) {
        //the union is the same as \s , but took \u00a0 (non breaking space) out
        //source https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Regular_expressions/Cheatsheet
        const allSubsequentWsExceptNonBreakingSpace =
          /[\f\n\r\t\v\u0020\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]+/g;
        childNodes[i].text = getText(childNodes[i]).replace(
          allSubsequentWsExceptNonBreakingSpace,
          " ",
        );
      }
    }
  }

  function stripCDataWrapper(childNodes: TransformNode[]) {
    for (let i = 0; i < childNodes.length; ++i) {
      if (childNodes[i].kind === SyntaxKind.CData) {
        childNodes[i].text = getText(childNodes[i]).slice(CDATA_PREFIX_LEN, -CDATA_POSTFIX_LEN);
      }
    }
  }

  function parseEscapeCharactersInContent(childNodes: TransformNode[]) {
    for (let node of childNodes) {
      if (node.kind === SyntaxKind.TextNode) {
        const escapedText = tryEscapeEntities(getText(node));
        if (escapedText !== null) {
          node.text = escapedText;
        }
      }
    }
  }

  function tryEscapeEntities(text: string): string | null {
    let newText = "";
    let startOfSubstr = 0;
    for (let i = 0; i < text.length; ++i) {
      if (text.charCodeAt(i) === CharacterCodes.ampersand) {
        switch (text.charCodeAt(i + 1)) {
          //&a
          case CharacterCodes.a:
            switch (text.charCodeAt(i + 2)) {
              //am
              case CharacterCodes.m:
                //amp;
                if (
                  text.charCodeAt(i + 3) === CharacterCodes.p &&
                  text.charCodeAt(i + 4) === CharacterCodes.semicolon
                ) {
                  newText = newText + text.substring(startOfSubstr, i) + "&";
                  i += 4;
                  startOfSubstr = i + 1;
                }
                break;
              //ap
              case CharacterCodes.p:
                //apos;
                if (
                  text.charCodeAt(i + 3) === CharacterCodes.o &&
                  text.charCodeAt(i + 4) === CharacterCodes.s &&
                  text.charCodeAt(i + 5) === CharacterCodes.semicolon
                ) {
                  newText = newText + text.substring(startOfSubstr, i) + "'";
                  i += 5;
                  startOfSubstr = i + 1;
                }
                break;
            }
            break;
          //&g
          case CharacterCodes.g:
            //\gt;
            if (
              text.charCodeAt(i + 2) === CharacterCodes.t &&
              text.charCodeAt(i + 3) === CharacterCodes.semicolon
            ) {
              newText = newText + text.substring(startOfSubstr, i) + ">";
              i += 3;
              startOfSubstr = i + 1;
            }
            break;
          //&l
          case CharacterCodes.l:
            //&lt;
            if (
              text.charCodeAt(i + 2) === CharacterCodes.t &&
              text.charCodeAt(i + 3) === CharacterCodes.semicolon
            ) {
              newText = newText + text.substring(startOfSubstr, i) + "<";
              i += 3;
              startOfSubstr = i + 1;
            }
            break;
          //&q
          case CharacterCodes.q:
            //&quot;
            if (
              text.charCodeAt(i + 2) === CharacterCodes.u &&
              text.charCodeAt(i + 3) === CharacterCodes.o &&
              text.charCodeAt(i + 4) === CharacterCodes.t &&
              text.charCodeAt(i + 5) === CharacterCodes.semicolon
            ) {
              newText = newText + text.substring(startOfSubstr, i) + '"';
              i += 5;
              startOfSubstr = i + 1;
            }
            break;
          //&n
          case CharacterCodes.n:
            //&nbsp;
            if (
              text.charCodeAt(i + 2) === CharacterCodes.b &&
              text.charCodeAt(i + 3) === CharacterCodes.s &&
              text.charCodeAt(i + 4) === CharacterCodes.p &&
              text.charCodeAt(i + 5) === CharacterCodes.semicolon
            ) {
              newText = newText + text.substring(startOfSubstr, i) + "\xa0";
              i += 5;
              startOfSubstr = i + 1;
            }
            break;
        }
      }
    }
    if (startOfSubstr === 0) {
      return null;
    }
    newText += text.substring(startOfSubstr);
    return newText;
  }

  function mergeConsecutiveTexts(childNodes: TransformNode[], shouldCollapseWs: boolean) {
    if (shouldCollapseWs) {
      collapseWhitespace(childNodes);
    }
    stripCDataWrapper(childNodes);

    for (let i = childNodes.length - 1; i > 0; --i) {
      const node = childNodes[i - 1];
      const nextNode = childNodes[i];

      if (node.kind === SyntaxKind.CData && nextNode.kind === SyntaxKind.TextNode) {
        childNodes[i - 1] = {
          pos: node.pos,
          end: nextNode.end,
          kind: SyntaxKind.CData,
          text: getText(node) + getText(nextNode),
        } as TransformNode;
        childNodes.pop();
      } else if (node.kind === SyntaxKind.CData && nextNode.kind === SyntaxKind.CData) {
        childNodes[i - 1] = {
          pos: node.pos,
          end: nextNode.end,
          kind: SyntaxKind.CData,
          text: getText(node) + getText(nextNode),
        } as TransformNode;
        childNodes.pop();
      } else if (node.kind === SyntaxKind.TextNode && nextNode.kind === SyntaxKind.TextNode) {
        if (getText(node).endsWith(" ") && getText(nextNode).startsWith(" ")) {
          node.text = getText(node).trimEnd();
        }
        childNodes[i - 1] = {
          pos: node.pos,
          end: nextNode.end,
          kind: SyntaxKind.TextNode,
          text: getText(node) + getText(nextNode),
        } as TransformNode;
        childNodes.pop();
      } else if (node.kind === SyntaxKind.TextNode && nextNode.kind === SyntaxKind.CData) {
        childNodes[i - 1] = {
          pos: node.pos,
          end: nextNode.end,
          kind: SyntaxKind.CData,
          text: getText(node) + getText(nextNode),
        } as TransformNode;
        childNodes.pop();
      }
    }
  }

  function parseEvent(value: any, nodeContainingValue: Node): any {
    if (typeof value !== "string") {
      // --- It must be a component definition in the event code
      return value;
    }

    // --- Parse the event code
    const parser = new Parser(value);
    try {
      const statements = parser.parseStatements();
      const parseId = ++lastParseId;
      const { directives, executableStatements } = extractEventHandlerDirectives(statements);
      const sourceId = `${fileId}#event-${parseId}`;
      let compiled: ParsedEventValue["compiled"] | undefined;
      let compiledUnsupported = false;
      if (parserOptions.compileEventHandlers) {
        try {
          compiled = compileEventAsyncStatements(executableStatements, {
            sourceId,
            sourceText: value,
            sourceUrl: createDebugSourceUrl(String(fileId)),
            displayName: String(fileId),
            sources: [
              {
                id: sourceId,
                url: createDebugSourceUrl(String(fileId)),
                displayName: String(fileId),
                sourceText: originalGetText(node),
              },
            ],
            sourceOrigin: {
              offset: (nodeContainingValue?.pos ?? 0) + 1,
              sourceText: originalGetText(node),
            },
          });
        } catch (error) {
          compiledUnsupported = true;
          const message =
            `Could not compile event handler ${sourceId}; ` +
            `falling back to interpreted execution. ${(error as Error).message}`;
          if (warnings) {
            warnings.push(message);
          }
        }
      }
      if (
        COMPILED_EVENT_HANDLER_SOURCE_LOGGING_ENABLED &&
        compiled &&
        parserOptions.logCompiledEventHandlerSource
      ) {
        logCompiledEventHandlerSource(compiled.sourceId, value, compiled.js);
      }
      return {
        __PARSED: true,
        statements: executableStatements,
        parseId,
        directives,
        // TODO: retrieve the event source code only in dev mode
        source: value,
        compiled,
        compiledUnsupported,
      } as ParsedEventValue;
    } catch {
      if (parser.errors.length > 0) {
        const errMsg = parser.errors[0];
        const diag = {
          code: errMsg.code,
          message: errMsg.text,
        };
        if (nodeContainingValue) {
          let diagPos: number;
          let diagEnd: number;
          const transformNode = nodeContainingValue as TransformNode;
          if (transformNode.originalKind !== undefined) {
            if (transformNode.originalKind === SyntaxKind.CData) {
              const afterCDataPos = transformNode.pos + CDATA_PREFIX_LEN;
              diagPos = afterCDataPos + errMsg.position;
              diagEnd = afterCDataPos + errMsg.end;
            } else {
              const afterContentPos = transformNode.pos;
              diagPos = afterContentPos + errMsg.position;
              diagEnd = afterContentPos + errMsg.end;
            }
          } else if (nodeContainingValue.kind === SyntaxKind.StringLiteral) {
            const afterQuotePos = nodeContainingValue.pos + 1;
            diagPos = afterQuotePos + errMsg.position;
            diagEnd = afterQuotePos + errMsg.end;
          } else if (nodeContainingValue.kind === SyntaxKind.TextNode) {
            const afterContentPos = nodeContainingValue.pos;
            diagPos = afterContentPos + errMsg.position;
            diagEnd = afterContentPos + errMsg.end;
          }
          reportError(diag, diagPos, diagEnd);
        } else {
          reportError(diag);
        }
      }
    }
  }

  /**
   * Parse the script tag and add it to its containing componenet's definition.
   * Reports errors encountered during script parsing.
   * @param comp The component containing the script tag
   */
  function processScriptTag(
    comp: ComponentDef | CompoundComponentDef,
    scriptTag: Node,
    getText: GetText,
  ) {
    if (getAttributes(scriptTag).length > 0) {
      reportError(DIAGS_TRANSFORM.scriptNoAttrs);
    }
    const scriptText = getText(scriptTag);
    const scriptContentPos = scriptText.indexOf(">") + 1;
    const scriptContent = scriptText.slice(scriptContentPos, scriptText.lastIndexOf("</"));

    if (scriptContent.trim().length === 0) {
      return;
    }

    comp.script = scriptContent;
    // --- Run the parse and collect on scripts
    const parser = new Parser(scriptContent);
    try {
      // --- We parse the module file to catch parsing errors
      parser.parseStatements();
      comp.scriptCollected = collectCodeBehindFromSource(fileId.toString(), scriptContent);

      // --- Merge pre-resolved imports if provided
      if (preResolvedImports) {
        comp.scriptCollected.functions = {
          ...preResolvedImports.functions,
          ...comp.scriptCollected.functions,
        };
        comp.scriptCollected.vars = {
          ...preResolvedImports.vars,
          ...comp.scriptCollected.vars,
        };
      }

      if (comp.scriptCollected.hasInvalidStatements) {
        comp.scriptError = new Error(
          `Only reactive variable and function definitions are allowed in a code-behind module.`,
        );
      }
    } catch (err) {
      if (parser.errors && parser.errors.length > 0) {
        const errMsg = parser.errors[0];
        const diag: TransformDiagPositionless = {
          code: errMsg.code,
          message: errMsg.text,
        };
        const errPos = scriptTag.pos + scriptContentPos + errMsg.position;
        const errEnd = scriptTag.pos + scriptContentPos + errMsg.end;
        reportError(diag, errPos, errEnd);
      } else {
        comp.scriptError = err;
      }
    }

    // --- We may have module parsing/execution errors
    const moduleErrors = comp.scriptCollected?.moduleErrors ?? {};
    if (Object.keys(moduleErrors).length > 0) {
      comp.scriptError = moduleErrors;
    }
  }
}

function createTextNodeCDataElement(textValue: string, originalKind?: SyntaxKind): Node {
  return {
    kind: SyntaxKind.ElementNode,
    originalKind,
    children: [
      { kind: SyntaxKind.OpenNodeStart },
      {
        kind: SyntaxKind.TagNameNode,
        children: [{ kind: SyntaxKind.Identifier, text: "TextNodeCData" }],
      },
      {
        kind: SyntaxKind.AttributeListNode,
        children: [
          {
            kind: SyntaxKind.AttributeNode,
            children: [
              {
                kind: SyntaxKind.AttributeKeyNode,
                children: [{ kind: SyntaxKind.Identifier, text: "value" }],
              },
              { kind: SyntaxKind.Equal },
              { kind: SyntaxKind.Identifier, text: `"${textValue}"` },
            ],
          },
        ],
      },
      { kind: SyntaxKind.NodeClose },
    ],
  } as unknown as Node;
}

function createTextNodeElement(textValue: string, originalKind?: SyntaxKind): Node {
  return {
    kind: SyntaxKind.ElementNode,
    originalKind,
    children: [
      { kind: SyntaxKind.OpenNodeStart },
      {
        kind: SyntaxKind.TagNameNode,
        children: [{ kind: SyntaxKind.Identifier, text: "TextNode" }],
      },
      {
        kind: SyntaxKind.AttributeListNode,
        children: [
          {
            kind: SyntaxKind.AttributeNode,
            children: [
              {
                kind: SyntaxKind.AttributeKeyNode,
                children: [{ kind: SyntaxKind.Identifier, text: "value" }],
              },
              { kind: SyntaxKind.Equal },
              { kind: SyntaxKind.Identifier, text: `"${textValue}"` },
            ],
          },
        ],
      },
      { kind: SyntaxKind.NodeClose },
    ],
  } as unknown as Node;
}

function reportError(
  diagnostic: TransformDiagPositionless,
  pos?: number,
  end?: number,
  contextPos?: number,
  contextEnd?: number,
): void {
  throw new TransformDiag(diagnostic, pos, end, contextPos, contextEnd);
}

function isComponent(obj: ComponentDef | CompoundComponentDef): obj is ComponentDef {
  return (obj as any).type;
}

function mergeValue(oldValue: any, itemValue: any): any {
  if (oldValue) {
    if (Array.isArray(oldValue)) {
      if (typeof oldValue === "string") {
        return [oldValue, itemValue];
      } else {
        oldValue.push(itemValue);
        return oldValue;
      }
    } else {
      return [oldValue, itemValue];
    }
  } else {
    return itemValue;
  }
}

function wrapWithFragment(wrappedChildren: Node[]): TransformNode {
  const nameNode = {
    kind: SyntaxKind.TagNameNode,
    children: [{ kind: SyntaxKind.Identifier, text: "Fragment" }],
  };
  return {
    kind: SyntaxKind.ElementNode,
    start: wrappedChildren[0].start,
    pos: wrappedChildren[0].pos,
    end: wrappedChildren[wrappedChildren.length - 1].end,
    children: [
      { kind: SyntaxKind.OpenNodeStart },
      nameNode,
      { kind: SyntaxKind.NodeEnd },
      { kind: SyntaxKind.ContentListNode, children: wrappedChildren },
      { kind: SyntaxKind.CloseNodeStart },
      nameNode,
      { kind: SyntaxKind.NodeEnd },
    ],
  } as TransformNode;
}

/**
 * Hoists scriptCollected from immediate Fragment children to the parent component.
 * This handles the case where script tags cause the parser to wrap children in a Fragment.
 * Only hoists if the script doesn't reference context variables (starting with $).
 */
function hoistScriptCollectedFromFragments(component: ComponentDef): void {
  if (!component.children || !Array.isArray(component.children)) {
    return;
  }

  for (const child of component.children) {
    if (child.type === "Fragment" && child.scriptCollected) {
      // Use AST-level analysis instead of a textual regex to detect $contextVar
      // references.  Iterating over the collected AST trees avoids false
      // positives from `$word` appearing inside string literals or comments.
      const hasContextVarReferences = scriptCollectedReadsContextVars(child.scriptCollected);

      // Only hoist if there are no context variable references
      // Context variables are component-specific and should remain at the iteration level
      if (!hasContextVarReferences) {
        // Guard against duplicate name collisions before merging.
        // If parent and Fragment declare the same var/function name, a later
        // re-parse of the concatenated script would see a duplicate declaration.
        const parentVars = Object.keys(component.scriptCollected?.vars ?? {});
        const parentFns = Object.keys(component.scriptCollected?.functions ?? {});
        const childVarKeys = Object.keys(child.scriptCollected.vars ?? {});
        const childFnKeys = Object.keys(child.scriptCollected.functions ?? {});
        const hasDuplicateVars = childVarKeys.some((k) => parentVars.includes(k));
        const hasDuplicateFns = childFnKeys.some((k) => parentFns.includes(k));
        if (hasDuplicateVars || hasDuplicateFns) {
          // Leave the Fragment's script in place rather than risk a duplicate-
          // declaration error during a later re-parse pass.
          continue;
        }

        // Merge the Fragment's scriptCollected into the parent
        if (!component.scriptCollected) {
          component.scriptCollected = child.scriptCollected;
          component.script = child.script;
        } else {
          // Merge vars and functions from the Fragment into the parent
          component.scriptCollected.vars = {
            ...component.scriptCollected.vars,
            ...child.scriptCollected.vars,
          };
          component.scriptCollected.functions = {
            ...component.scriptCollected.functions,
            ...child.scriptCollected.functions,
          };
          component.script = (component.script || "") + "\n" + (child.script || "");
        }
        // Remove scriptCollected from the Fragment since we've hoisted it
        delete child.scriptCollected;
        delete child.script;
      }
    }
  }
}

/**
 * Returns true if any collected declaration in `sc` reads an identifier that
 * starts with `$` (a context variable injected by a parent component such as
 * `$item` or `$index`).  Uses the parsed AST trees directly instead of a
 * textual regex so that `$word` inside string literals or comments does not
 * trigger a false positive.
 */
function scriptCollectedReadsContextVars(sc: CollectedDeclarations): boolean {
  const check = (tree: unknown): boolean => {
    if (!tree) return false;
    try {
      const deps = collectVariableDependencies(tree as any);
      return deps.some((d) => d.startsWith("$"));
    } catch {
      // If the AST can't be walked, fall back to conservative: treat as
      // having context var references to avoid a lost dependency.
      return true;
    }
  };
  for (const decl of Object.values(sc.vars ?? {})) {
    // vars entries are { tree: Expression, ... }
    if (check((decl as any).tree)) return true;
  }
  for (const decl of Object.values(sc.functions ?? {})) {
    // functions entries are stored directly as ArrowExpression (not wrapped in { tree })
    if (check(decl)) return true;
  }
  return false;
}

function getAttributes(node: Node): Node[] {
  return node.children?.find((c) => c.kind === SyntaxKind.AttributeListNode)?.children ?? [];
}

function getChildNodes(node: Node): Node[] {
  return node.children?.find((c) => c.kind === SyntaxKind.ContentListNode)?.children ?? [];
}

function withNewChildNodes(node: Node, newChildren: Node[]) {
  const childrenListIdx = node.children?.findIndex((c) => c.kind === SyntaxKind.ContentListNode);
  if (childrenListIdx === undefined || childrenListIdx === -1) {
    return node;
  }
  const contentListChild = node.children![childrenListIdx];
  return new Node(node.kind, node.pos ?? 0, node.end ?? 0, node.triviaBefore, [
    ...node.children!.slice(0, childrenListIdx),
    new Node(
      contentListChild.kind,
      contentListChild.pos ?? 0,
      contentListChild.end ?? 0,
      undefined,
      newChildren,
    ),
    ...node.children!.slice(childrenListIdx),
  ]);
}

function desugarKeyOnlyAttrs(attrs: Node[]) {
  for (let attr of attrs) {
    if (attr.children?.length === 1) {
      const eq = {
        kind: SyntaxKind.Equal,
      } as Node;
      const value = {
        kind: SyntaxKind.StringLiteral,
        text: '"true"',
      } as TransformNode;
      attr.children!.push(eq, value);
    }
  }
}

function addToNamespaces(
  namespaceStack: Map<string, string>[],
  comp: any,
  nsKey: string,
  value: string,
) {
  let nsCommaSeparated = value.split(":");
  if (nsCommaSeparated.length > 2) {
    // Parser already emits nsValueIncorrect for this.
    return;
  }

  let nsValue = value;
  if (nsCommaSeparated.length === 2) {
    if (nsCommaSeparated[0] != COMPONENT_NAMESPACE_SCHEME) {
      // Parser already emits nsSchemeIncorrect for this.
      return;
    }
    nsValue = nsCommaSeparated[1];
  }

  if (nsValue.includes("#")) {
    // Parser already emits nsValueIncorrect for this.
    return;
  }

  switch (nsValue) {
    case COMPONENT_NAMESPACE_SCHEME:
      nsValue = nsKey;
      break;
    case APP_NS_KEY:
      nsValue = APP_NS_VALUE;
      break;
    case CORE_NS_KEY:
      nsValue = CORE_NAMESPACE_VALUE;
      break;
  }

  const compNamespaces = namespaceStack[namespaceStack.length - 1];
  if (compNamespaces.has(nsKey)) {
    // Parser already emits duplXmlns for this — skip silently.
    return;
  }
  compNamespaces.set(nsKey, nsValue);
}

function getComponentName(node: Node, getText: GetText) {
  const nameTokens = node.children!.find((c) => c.kind === SyntaxKind.TagNameNode)!.children!;
  const name = getText(nameTokens.at(-1));
  return name;
}

function getNamespaceResolvedComponentName(
  node: Node,
  getText: GetText,
  namespaceStack: Map<string, string>[],
) {
  const nameTokens = node.children!.find((c) => c.kind === SyntaxKind.TagNameNode)!.children!;
  const name = getText(nameTokens.at(-1));

  if (nameTokens.length === 1) {
    return name;
  }

  const namespace = getText(nameTokens[0]);

  if (namespaceStack.length === 0) {
    // Parser already emits rootCompNoNamespace for this.
    return namespace + "." + name;
  }

  let resolvedNamespace = undefined;
  for (let i = namespaceStack.length - 1; i >= 0; --i) {
    resolvedNamespace = namespaceStack[i].get(namespace);
    if (resolvedNamespace !== undefined) {
      break;
    }
  }
  if (resolvedNamespace === undefined) {
    // Parser already emits nsNotFound for this.
    return namespace + "." + name;
  }

  return resolvedNamespace + "." + name;
}

/**
 * @param name - The name of the event in camelCase, with "on" prefix.
 */
export function stripOnPrefix(name: string) {
  return name[2].toLowerCase() + name.substring(3);
}

function splitUsesValue(value: string) {
  return value.split(",").map((v) => v.trim());
}
