@use "../../components-core/theming/themes" as t;

@layer components {
  .wrapper {
    display: flex;
    gap: t.$space-2;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    color: t.$textColor-subtitle;
  }

  .clickable {
    cursor: pointer;

    &:hover {
      opacity: 0.8;
    }

    &:focus {
      outline: none;
    }
  }
}
